#include <memory>
#include <iostream>

int main() {
    // std::auto_ptr<int> p1(new int(10)); // C++03/Deprecated
    // std::auto_ptr<int> p2 = p1;
    // std::cout << p1.get(); // Output: 0 (p1 is null/invalid)

    std::shared_ptr<int> s1(new int(20));
    std::shared_ptr<int> s2 = s1;

    // Shared ownership: both remain valid
    std::cout << "s1 value: " << *s1 << "\n";
    std::cout << "s2 value: " << *s2 << "\n";

    // Unique ownership (Move semantics required)
    std::unique_ptr<int> u1(new int(30));
    std::unique_ptr<int> u2 = std::move(u1); 
    // u1.get() is now nullptr
    // std::cout << *u1; // DANGER: UB
}
